# Generated by GitHub Copilot - Oct-05-2026
def test_asr_timing_repair_preserves_raw_evidence():
    """ASR anomalies are visible and repaired intervals never overlap."""
    original = [{"word": "a", "start": 0, "end": 1, "confidence": .9},
                {"word": "b", "start": .8, "end": 2, "confidence": .4},
                {"word": "c", "start": float("nan"), "end": 3}]
    words, anomalies, unaligned = normalize_asr_timestamps(original, 5)
    assert words[1]["start"] == words[0]["end"]
    assert words[1]["raw_start"] == .8
    assert len(anomalies) == 2 and len(unaligned) == 1
    assert original[1]["start"] == .8
    data = {"words": words}
    annotate_review(data, .6)
    assert words[1]["needs_review"]


