def test_repetition_region_is_not_mislabeled_low_model_probability():
    """Review flags and model probability thresholds represent different quantities."""
    from ldporto.transcription import transcription_metrics
    words=[{'word':'repeticao','word_id':f'W{index}','start':index,'end':index+.5,'confidence':.95} for index in range(6)]
