# Generated by GitHub Copilot - Oct-05-2026
def test_low_confidence_alternatives_do_not_replace_canonical_words():
    """A higher model probability alone is not independent correctness evidence."""
    hypothesis = {"words": [{"word": "inventado", "start": 0, "end": 1, "confidence": .99}]}
    evidence = alternative_evidence(hypothesis, 0, 2)
    assert evidence["mean_model_probability"] == .99
    assert not evidence["replacement_permitted"]
    data = {"words": [{"word": "literal", "start": 0, "end": 1, "confidence": .2}]}
    annotate_review(data, .6)
    assert data["words"][0]["word"] == "literal" and data["words"][0]["needs_review"]


# Generated by GitHub Copilot - Oct-05-2026
def test_exclusive_alignment_keeps_overlap_evidence():
    """Community-1 exclusive turns align words; normal overlapping turns survive."""
    transcript = validate_import({"words": [{"word": "Ola.", "start": 1, "end": 2}]}, 5)
    diarization = {"turns": [{"start": 0, "end": 3, "speaker": "A"}, {"start": 1, "end": 2, "speaker": "B"}],
                   "exclusive_turns": [{"start": 0, "end": 1, "speaker": "A"}, {"start": 1, "end": 2, "speaker": "B"}],
                   "speakers": [{"speaker_id": "A"}, {"speaker_id": "B"}]}
    diarization["overlaps"] = overlap_intervals(diarization["turns"])
    before = deepcopy(diarization["turns"])
    aligned = align_speakers(transcript, diarization)
    assert aligned["words"][0]["speaker"] == "B"
    assert aligned["words"][0]["speech_overlap"]
    assert aligned["words"][0]["speaker_assignment_method"] == "exclusive_temporal_alignment"
    assert diarization["turns"] == before and diarization["overlaps"]


