# Generated by GitHub Copilot - Oct-05-2026
def track_fixture(specifications):
    """Construct detector tracklets with explicit synthetic face evidence."""
    rows = []
    for track_id, source_id, start, end, embedding in specifications:
        for time in (start, (start + end) / 2, end):
            rows.append({"track_id": track_id, "person_id": source_id, "time": time,
                         "scene_id": "SCENE_" + str(int(start)), "face_visible": True,
                         "face_embedding": embedding, "tracking_method": "temporal_iou"})
    return {"observations": rows, "people": [{"person_id": row["person_id"]} for row in rows],
            "frames": [{"time": row["time"], "visible_people": [row["person_id"]]} for row in rows]}


# Generated by GitHub Copilot - Oct-05-2026
def test_strong_face_evidence_merges_across_cuts():
    """The Re-ID stage actually merges separate online-tracker identities."""
    from ldporto.person_reid import build_person_identities
    vision = track_fixture([("T1", "P1", 0, 2, [1, 0]), ("T2", "P2", 5, 7, [1, 0])])
    data = build_person_identities(vision)["data"]
    assert len(data["identities"]) == 1
    assert data["metrics"]["reid_merge_count"] == 1
    assert data["tracklet_to_person"]["T1"] == data["tracklet_to_person"]["T2"]


