def test_microtracks_do_not_explode_participants():
    """Hundreds of 0.2s tracks remain raw evidence instead of participants."""
    from ldporto.person_reid import build_person_identities, apply_person_identities
    from ldporto.understanding import build_participants
    vision = track_fixture([(f"T{index}", f"P{index}", index, index + .2, None) for index in range(100)])
    data = build_person_identities(vision)["data"]
    persistent = apply_person_identities(vision, data)
    assert data["metrics"]["raw_track_count"] == 100
    assert data["metrics"]["micro_track_count"] == 100
    assert not persistent["people"]
    assert len(persistent["tracklet_observations"]) == 300
    assert build_participants({"segments": []}, {"speakers": []}, persistent, [], []) == []


